<?php
session_start();if(!isset($_SESSION['representative_id'])){header('Location: index.html');exit;}
require_once 'db_connect.php';$repId=(int)$_SESSION['representative_id'];
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function pageStart($title){echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).' | Moving On Up</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="portal.css"></head><body><div class="portal"><header><strong>↗ MOVING ON UP</strong><span>'.h($_SESSION['representative_name']).'</span></header><nav><a href="search_account.php">Search Account</a><a href="book_move.php">Book Move</a><a href="cancel_move.php">Cancel Move</a><a href="special_instructions.php">Special Instructions</a><a href="update_instructions.php">Update Instructions</a><a href="add_client.php">New Client</a><a href="logout.php">Log out</a></nav><main><h1>'.h($title).'</h1>';}
function pageEnd(){echo '</main></div></body></html>';}
function field($name,$label,$type='text',$required=true,$value=''){echo '<label class="portal-field">'.h($label).'<input name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" '.($required?'required':'').'></label>';}
function clientSelect($pdo,$repId){$s=$pdo->prepare('SELECT c.client_id,c.first_name,c.last_name FROM clients c JOIN representative_clients rc ON c.client_id=rc.client_id WHERE rc.representative_id=? ORDER BY c.last_name,c.first_name');$s->execute([$repId]);echo '<label class="portal-field">Client<select name="client_id" required><option value="">Select client</option>';foreach($s as $r)echo '<option value="'.h($r['client_id']).'">'.h($r['first_name'].' '.$r['last_name'].' (#'.$r['client_id'].')').'</option>';echo '</select></label>';}
function eventSelect($pdo,$repId){$s=$pdo->prepare('SELECT m.moving_id,c.first_name,c.last_name,m.moving_date FROM moving_events m JOIN clients c ON c.client_id=m.client_id WHERE m.representative_id=? ORDER BY m.moving_date');$s->execute([$repId]);echo '<label class="portal-field">Moving event<select name="moving_id" required><option value="">Select event</option>';foreach($s as $r)echo '<option value="'.h($r['moving_id']).'">'.h($r['first_name'].' '.$r['last_name'].' — '.$r['moving_date'].' (#'.$r['moving_id'].')').'</option>';echo '</select></label>';}
function message($s){echo '<p class="notice">'.h($s).'</p>';}
function submit($s){echo '<button type="submit">'.h($s).'</button></form>';}
